<?php require __DIR__ . '/../partials/header.php'; ?>
<div class="card" style="max-width:700px;margin:0 auto;"><div class="card-header"><h1>Dynamic Pricing</h1><p>Add new supply items or edit prices.</p></div><?php if($generalErr):?><div class="alert alert-error"><?php echo e($generalErr);?></div><?php endif;?><?php if($successMsg):?><div class="alert alert-success"><?php echo e($successMsg);?></div><?php endif;?>
<form method="post" action="<?php echo e(url_for('vendor','pricing'));?>"><?php echo csrf_field();?><input type="hidden" name="action" value="add"><div class="field"><label>New Product Name</label><input type="text" name="name"></div><div class="field"><label>Price (TK)</label><input type="number" step="0.01" min="0" name="price"></div><button class="btn btn-primary btn-block">Add Supply Item</button></form></div>
<div class="card"><div class="card-header"><h2>Your Supply Items</h2></div><?php if(!$products):?><p class="muted">No items yet.</p><?php else:?><table class="data-table"><tr><th>ID</th><th>Name</th><th>Price</th><th>Policy</th><th>Added</th><th>Actions</th></tr><?php foreach($products as $p):?><tr><td>#<?php echo e($p['id']);?></td><td><?php echo e($p['name']);?></td><td>TK <?php echo e(number_format((float)$p['price'],2));?></td><td class="small"><?php echo $p['return_policy']?e(mb_strimwidth($p['return_policy'],0,40,'...')):'<span class="muted">—</span>';?></td><td class="small"><?php echo e($p['created_at']);?></td><td><form method="post" class="inline-form" action="<?php echo e(url_for('vendor','pricing'));?>"><?php echo csrf_field();?><input type="hidden" name="action" value="edit"><input type="hidden" name="product_id" value="<?php echo e($p['id']);?>"><input type="number" step="0.01" min="0" name="price" value="<?php echo e($p['price']);?>" style="width:110px;padding:6px;"><button class="btn btn-primary btn-small">Update</button></form> <form method="post" class="inline-form" action="<?php echo e(url_for('vendor','pricing'));?>"><?php echo csrf_field();?><input type="hidden" name="action" value="delete"><input type="hidden" name="product_id" value="<?php echo e($p['id']);?>"><button class="btn btn-secondary btn-small" data-confirm="Delete product #<?php echo e($p['id']);?>?">Delete</button></form></td></tr><?php endforeach;?></table><?php endif;?></div>
